/**
 * Cloudflare entry point: the OpenNext app for web requests, plus two scheduled jobs
 * (see "triggers" in wrangler.jsonc):
 *   "17 *\/6 * * *"  catalog: new Microsoft Learn courses + link check (src/lib/catalog-sync.ts)
 *   "0 3 * * *"      email alerts, at most weekly per learner (src/lib/email-alerts.ts)
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { runCatalogSync, type SyncEnv } from "./src/lib/catalog-sync";
import { runEmailAlerts, type EmailEnv } from "./src/lib/email-alerts";

const EMAIL_CRON = "0 3 * * *";

const worker = {
  fetch: handler.fetch,

  async scheduled(event: { cron: string }, env: SyncEnv & EmailEnv, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const job = event.cron === EMAIL_CRON ? ["email alerts", runEmailAlerts(env)] as const : ["catalog sync", runCatalogSync(env)] as const;
    ctx.waitUntil(
      job[1].then(
        (r) => console.log(job[0], JSON.stringify(r)),
        (e) => console.error(`${job[0]} failed`, (e as Error).message),
      ),
    );
  },
};

export default worker;

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
